  public static bool masterMode => (double) Main.Difficulty >= (double) GameDifficultyLevel.Master;

  public static bool expertMode => (double) Main.Difficulty >= (double) GameDifficultyLevel.Expert;

  public static float Difficulty
  {
    get
    {
      float difficulty = GameDifficultyLevel.Classic;
      if (Main.ActiveWorldFileData != null)
      {
        if (Main._gameModeDifficultyOverride.HasValue)
        {
          difficulty = Main._gameModeDifficultyOverride.Value;
        }
        else
        {
          switch (Main.GameMode)
          {
            case 1:
              difficulty = GameDifficultyLevel.Expert;
              break;
            case 2:
              difficulty = GameDifficultyLevel.Master;
              break;
          }
        }
        if (Main.getGoodWorld)
          ++difficulty;
      }
      return difficulty;
    }
  }

  public static Microsoft.Xna.Framework.Color GetColorForCurrentDifficulty(bool includeLegendary = true)
  {
    if (includeLegendary && Main.getGoodWorld && Main.masterMode)
      return Main.GetColorForDifficulty(GameDifficultyLevel.Legendary);
    if (Main.masterMode)
      return Main.GetColorForDifficulty(GameDifficultyLevel.Master);
    if (Main.expertMode)
      return Main.GetColorForDifficulty(GameDifficultyLevel.Expert);
    return Main.IsJourneyMode ? Main.GetColorForDifficulty(GameDifficultyLevel.Journey) : Main.GetColorForDifficulty(GameDifficultyLevel.Classic);
  }

  public static Microsoft.Xna.Framework.Color GetColorForDifficulty(float gameDifficultyLevel)
  {
    if ((double) gameDifficultyLevel <= (double) GameDifficultyLevel.Journey)
      return Main.creativeModeColor;
    if ((double) gameDifficultyLevel <= (double) GameDifficultyLevel.Classic)
      return Microsoft.Xna.Framework.Color.White;
    if ((double) gameDifficultyLevel <= (double) GameDifficultyLevel.Expert)
      return Main.mcColor;
    if ((double) gameDifficultyLevel <= (double) GameDifficultyLevel.Master)
      return Main.hcColor;
    return (double) gameDifficultyLevel <= (double) GameDifficultyLevel.Legendary ? Main.legendaryModeColor : Microsoft.Xna.Framework.Color.White;
  }

