  private static void DedServ_SeedFlagsMenu()
  {
    List<AWorldGenerationOption> list = WorldGenerationOptions.Options.ToList<AWorldGenerationOption>();
    foreach (AWorldGenerationOption generationOption in list)
      generationOption.Load();
    string str1 = "[x]";
    string str2 = "[ ]";
    string str3 = "\t";
    while (true)
    {
      Console.Clear();
      Console.WriteLine(Language.GetTextValue("CLI.Server", (object) Main.versionNumber2));
      Console.WriteLine();
      int num = 0;
      foreach (AWorldGenerationOption generationOption in list)
      {
        ++num;
        Console.Write($"{num,-2}");
        Console.Write(str3);
        Console.Write(generationOption.Enabled ? str1 : str2);
        Console.Write(str3);
        Console.Write((object) generationOption.Title);
        Console.WriteLine();
      }
      Console.WriteLine();
      Console.Write(Language.GetTextValue("CLI.EnterSeedToggleNumber"));
      string s = Main.ReadLineInput();
      if (!(s == string.Empty))
      {
        int result;
        if (!int.TryParse(s, out result))
        {
          Console.Clear();
        }
        else
        {
          int index = result - 1;
          if (index < 0 || index >= list.Count)
            Console.Clear();
          else
            list[index].Enabled = !list[index].Enabled;
        }
      }
      else
        break;
    }
  }

  private static void WriteFancyWorldLoadErrorToConsole()
  {
    Console.WriteLine();
    if (WorldFile.LastThrownLoadException == null)
      return;
    Console.WriteLine(WorldFile.LastThrownLoadException.ToString());
  }

  public static void startDedInput()
  {
    new Thread(new ThreadStart(Main.startDedInputCallBack))
    {
      IsBackground = true,
      Name = "Server Input Thread"
    }.Start();
  }

  public static void startDedInputCallBack()
  {
    while (!Netplay.Disconnect)
    {
      Console.Write(": ");
      string text1 = Main.ReadLineInput();
      try
      {
        if (Language.GetText("CLI.Help_Command").EqualsCommand(text1))
        {
          Console.WriteLine(Language.GetTextValue("CLI.AvailableCommands"));
          Console.WriteLine("");
          List<string> stringList = new List<string>()
          {
            "Help",
            "Playing",
            "Clear",
            "Exit",
            "ExitNoSave",
            "Save",
            "Kick",
            "Ban",
            "Password",
            "SetPassword",
            "Version",
            "Time",
            "Port",
            "MaxPlayers",
            "Say",
            "MOTD",
            "SetMOTD",
            "Dawn",
            "Noon",
            "Dusk",
            "Midnight",
            "Settle",
            "Seed"
          };
          int val1 = 0;
          for (int index = 0; index < stringList.Count; ++index)
          {
            string text2 = Language.Exists($"CLI.{stringList[index]}_Example") ? Language.GetTextValue($"CLI.{stringList[index]}_Example") : Language.GetTextValue($"CLI.{stringList[index]}_Command");
            val1 = Math.Max(val1, Main.EstimatedMonospacedWidth(text2));
          }
          int num = (val1 + 1) / 8;
          for (int index = 0; index < stringList.Count; ++index)
          {
            string text3 = Language.Exists($"CLI.{stringList[index]}_Example") ? Language.GetTextValue($"CLI.{stringList[index]}_Example") : Language.GetTextValue($"CLI.{stringList[index]}_Command");
            Console.WriteLine(text3 + new string('\t', num - Main.EstimatedMonospacedWidth(text3) / 8) + Language.GetTextValue($"CLI.{stringList[index]}_Description"));
          }
        }
        else if (Language.GetText("CLI.Settle_Command").EqualsCommand(text1))
        {
          if (!Terraria.Liquid.panicMode)
            Terraria.Liquid.StartPanic();
          else
            Console.WriteLine(Language.GetTextValue("CLI.WaterIsAlreadySettling"));
        }
        else if (Language.GetText("CLI.Dawn_Command").EqualsCommand(text1))
        {
          Main.dayTime = true;
          Main.time = 0.0;
          NetMessage.SendData(7);
        }
        else if (Language.GetText("CLI.Dusk_Command").EqualsCommand(text1))
        {
          Main.dayTime = false;
          Main.time = 0.0;
          NetMessage.SendData(7);
        }
        else if (Language.GetText("CLI.Noon_Command").EqualsCommand(text1))
        {
          Main.dayTime = true;
          Main.time = 27000.0;
          NetMessage.SendData(7);
        }
        else if (Language.GetText("CLI.Midnight_Command").EqualsCommand(text1))
        {
          Main.dayTime = false;
          Main.time = 16200.0;
          NetMessage.SendData(7);
        }
        else if (Language.GetText("CLI.ExitNoSave_Command").EqualsCommand(text1))
        {
          Netplay.SaveOnServerExit = false;
          Netplay.Disconnect = true;
        }
        else if (Language.GetText("CLI.Exit_Command").EqualsCommand(text1))
        {
          Netplay.Disconnect = true;
          SocialAPI.Shutdown();
        }
        else if (Language.GetText("CLI.FPS_Command").EqualsCommand(text1))
        {
          if (!Main.dedServFPS)
          {
            Main.dedServFPS = true;
            Main.fpsTimer.Reset();
          }
          else
          {
            Main.dedServCount1 = 0;
            Main.dedServCount2 = 0;
            Main.dedServFPS = false;
          }
        }
        else if (Language.GetText("CLI.Save_Command").EqualsCommand(text1))
          WorldFile.SaveWorld();
        else if (Language.GetText("CLI.Time_Command").EqualsCommand(text1))
        {
          string textValue = Language.GetTextValue("GameUI.TimeAtMorning");
          double time = Main.time;
          if (!Main.dayTime)
            time += 54000.0;
          double num1 = time / 86400.0 * 24.0 - 7.5 - 12.0;
          if (num1 < 0.0)
            num1 += 24.0;
          if (num1 >= 12.0)
            textValue = Language.GetTextValue("GameUI.TimePastMorning");
          int num2 = (int) num1;
          double num3 = (double) (int) ((num1 - (double) num2) * 60.0);
          string str = string.Concat((object) num3);
          if (num3 < 10.0)
            str = "0" + str;
          if (num2 > 12)
            num2 -= 12;
          if (num2 == 0)
            num2 = 12;
          Console.WriteLine(Language.GetTextValue("CLI.Time", (object) $"{(object) num2}:{str} {textValue}"));
        }
        else if (Language.GetText("CLI.MaxPlayers_Command").EqualsCommand(text1))
          Console.WriteLine(Language.GetTextValue("CLI.PlayerLimit", (object) Main.maxNetPlayers));
        else if (Language.GetText("CLI.Port_Command").EqualsCommand(text1))
          Console.WriteLine(Language.GetTextValue("CLI.Port", (object) Netplay.ListenPort));
        else if (Language.GetText("CLI.Version_Command").EqualsCommand(text1))
          Console.WriteLine(Language.GetTextValue("CLI.Server", (object) Main.versionNumber));
        else if (Language.GetText("CLI.Clear_Command").EqualsCommand(text1))
        {
          try
          {
            Console.Clear();
          }
          catch
          {
          }
        }
        else if (Language.GetText("CLI.Playing_Command").EqualsCommand(text1))
        {
          int num = 0;
          for (int index = 0; index < (int) byte.MaxValue; ++index)
          {
            if (Main.player[index].active)
            {
              ++num;
              Console.WriteLine($"{Main.player[index].name} ({(object) Netplay.Clients[index].Socket.GetRemoteAddress()})");
            }
          }
          switch (num)
          {
            case 0:
              Console.WriteLine(Language.GetTextValue("CLI.NoPlayers"));
              continue;
            case 1:
              Console.WriteLine(Language.GetTextValue("CLI.OnePlayerConnected"));
              continue;
            default:
              Console.WriteLine(Language.GetTextValue("CLI.PlayersConnected", (object) num));
              continue;
          }
        }
        else if (!(text1 == ""))
        {
          if (Language.GetText("CLI.MOTD_Command").EqualsCommand(text1))
          {
            if (Main.motd == "")
              Console.WriteLine(Language.GetTextValue("CLI.NoMOTD", (object) Main.worldName));
            else
              Console.WriteLine(Language.GetTextValue("CLI.MOTD", (object) Main.motd));
          }
          else
          {
            string remainder;
            if (Language.GetText("CLI.MOTD_Command").ParseCommandPrefix(text1, out remainder))
              Main.motd = remainder;
            else if (Language.GetText("CLI.Password_Command").EqualsCommand(text1))
            {
              if (Netplay.ServerPassword == "")
                Console.WriteLine(Language.GetTextValue("CLI.NoPassword"));
              else
                Console.WriteLine(Language.GetTextValue("CLI.Password", (object) Netplay.ServerPassword));
            }
            else if (Language.GetText("CLI.SetPassword_Command").ParseCommandPrefix(text1, out remainder))
            {
              if (string.IsNullOrWhiteSpace(remainder))
              {
                Netplay.ServerPassword = "";
                Console.WriteLine(Language.GetTextValue("CLI.PasswordDisabled"));
              }
              else
              {
                Netplay.ServerPassword = remainder;
                Console.WriteLine(Language.GetTextValue("CLI.PasswordSet", (object) Netplay.ServerPassword));
              }
            }
            else if (Language.GetText("CLI.Say_Command").ParseCommandPrefix(text1, out remainder))
            {
              if (string.IsNullOrWhiteSpace(remainder))
              {
                Console.WriteLine(Language.GetTextValue("CLI.Say_Usage"));
              }
              else
              {
                string str = remainder;
                Console.WriteLine(Language.GetTextValue("CLI.ServerMessage", (object) str));
                ChatHelper.BroadcastChatMessage(NetworkText.FromKey("CLI.ServerMessage", (object) str), new Microsoft.Xna.Framework.Color((int) byte.MaxValue, 240 /*0xF0*/, 20));
              }
            }
            else if (Language.GetText("CLI.Kick_Command").ParseCommandPrefix(text1, out remainder))
            {
              if (string.IsNullOrWhiteSpace(remainder))
              {
                Console.WriteLine(Language.GetTextValue("CLI.Kick_Usage"));
              }
              else
              {
                string lower = remainder.ToLower();
                for (int remoteClient = 0; remoteClient < (int) byte.MaxValue; ++remoteClient)
                {
                  if (Main.player[remoteClient].active && Main.player[remoteClient].name.ToLower() == lower)
                    NetMessage.SendData(2, remoteClient, text: NetworkText.FromKey("CLI.KickMessage"));
                }
              }
            }
            else if (Language.GetText("CLI.Seed_Command").EqualsCommand(text1))
            {
              if (Main.ActiveWorldFileData == null || !Main.ActiveWorldFileData.HasValidSeed)
                Console.WriteLine(Language.GetTextValue("CLI.NoValidSeed"));
              else
                Console.WriteLine(Language.GetTextValue("CLI.DisplaySeed", (object) Main.ActiveWorldFileData.GetFullSeedText()));
            }
            else if (Language.GetText("CLI.Ban_Command").ParseCommandPrefix(text1, out remainder))
            {
              if (string.IsNullOrWhiteSpace(remainder))
              {
                Console.WriteLine(Language.GetTextValue("CLI.Ban_Usage"));
              }
              else
              {
                string lower = remainder.ToLower();
                for (int index = 0; index < (int) byte.MaxValue; ++index)
                {
                  if (Main.player[index].active && Main.player[index].name.ToLower() == lower)
                  {
                    Netplay.AddBan(index);
                    NetMessage.SendData(2, index, text: NetworkText.FromKey("CLI.BanMessage"));
                  }
                }
              }
            }
            else if (!ChatManager.DebugCommands.Process((byte) Main.myPlayer, "/" + text1))
              Console.WriteLine(Language.GetTextValue("CLI.InvalidCommand"));
          }
        }
      }
      catch
      {
        Console.WriteLine(Language.GetTextValue("CLI.InvalidCommand"));
      }
    }
  }

  private static int EstimatedMonospacedWidth(string text)
  {
    int num = 0;
    foreach (char ch in text)
    {
      if (ch >= '　' && ch <= '〿')
        num += 2;
      else if (ch >= '一' && ch <= '\u9FFF')
        num += 2;
      else
        ++num;
    }
    return num;
  }

  private static string ReadLineInput()
  {
    string str;
    do
    {
      str = Console.ReadLine();
    }
    while (str == null);
    return str;
  }

  public static bool IsFastForwardingTime()
  {
    return Main.fastForwardTimeToDawn || Main.fastForwardTimeToDusk;
  }

  public static void Sundialing()
  {
    if (Main.sundialCooldown != 0)
      return;
    if (Main.netMode == 1)
    {
      NetMessage.SendData(51, number: Main.myPlayer, number2: 3f);
    }
    else
    {
      Main.fastForwardTimeToDawn = true;
      Main.sundialCooldown = 8;
      NetMessage.SendData(7);
    }
  }

  public static void Moondialing()
  {
    if (Main.moondialCooldown != 0)
      return;
    if (Main.netMode == 1)
    {
      NetMessage.SendData(51, number: Main.myPlayer, number2: 6f);
    }
    else
    {
      Main.fastForwardTimeToDusk = true;
      Main.moondialCooldown = 8;
      NetMessage.SendData(7);
    }
  }

  public static void UpdateTimeRate()
  {
    if (Main.IsFastForwardingTime())
    {
      Main.dayRate = 60;
      Main.desiredWorldTilesUpdateRate = 1;
    }
    else
    {
      int num1 = CreativePowerManager.Instance.GetPower<CreativePowers.FreezeTime>().Enabled ? 1 : 0;
      int targetTimeRate = CreativePowerManager.Instance.GetPower<CreativePowers.ModifyTimeRate>().TargetTimeRate;
      bool flag = Main.CurrentFrameFlags.SleepingPlayersCount == Main.CurrentFrameFlags.ActivePlayersCount && Main.CurrentFrameFlags.SleepingPlayersCount > 0;
      int num2 = targetTimeRate;
      if (!Main.gameMenu & flag)
        num2 *= 5;
      if (num1 != 0)
        num2 = 0;
      Main.dayRate = num2;
      Main.desiredWorldTilesUpdateRate = num2;
      if (!Main.gameMenu)
        return;
      Main.dayRate = 1;
      Main.desiredWorldTilesUpdateRate = 1;
    }
  }

  public Main()
  {
    Main.instance = this;
    Main.UnpausedUpdateSeed = (ulong) Guid.NewGuid().GetHashCode();
    this.Exiting += new EventHandler<EventArgs>(this.Main_Exiting);
    if (Main.dedServ)
      return;
    Main.Map = new WorldMap(Main.maxTilesX, Main.maxTilesY);
    Main.Configuration.Load();
    Main.graphics = new GraphicsDeviceManager(this as Game);
    this.Content.RootDirectory = "Content";
  }

  private static void SetDisplayMonitor()
  {
    Main.Configuration.Get<string>("Display", "");
    if (!Program.IsXna)
      return;
    Main.graphics.PreparingDeviceSettings += new EventHandler<PreparingDeviceSettingsEventArgs>(Main.SetMonitorOnce);
  }

  private static void SetMonitorOnce(object sender, PreparingDeviceSettingsEventArgs e)
  {
    string displayName = Main.Configuration.Get<string>("Display", "");
    GraphicsAdapter graphicsAdapter = GraphicsAdapter.Adapters.Where<GraphicsAdapter>((Func<GraphicsAdapter, bool>) (adapter => adapter.DeviceName == displayName)).FirstOrDefault<GraphicsAdapter>();
    if (graphicsAdapter != null)
      e.GraphicsDeviceInformation.Adapter = graphicsAdapter;
    Main.graphics.PreparingDeviceSettings -= new EventHandler<PreparingDeviceSettingsEventArgs>(Main.SetMonitorOnce);
  }

