  internal void ContentFileUpdated(IContentSource contentSource, string path, string fullPath)
  {
    try
    {
      if (!LanguageManager.Instance.HotReloadContentFile(contentSource, path, fullPath))
        return;
      Main.NewTextMultiline(Language.GetTextValue("HotReload.LocalizationsReloaded", (object) path), c: new Microsoft.Xna.Framework.Color(250, 250, 0));
    }
    catch (Exception ex)
    {
      Main.NewTextMultiline(Language.GetTextValue("HotReload.ErrorUpdating", (object) path, (object) ex.Message), c: new Microsoft.Xna.Framework.Color(250, 50, 0));
    }
  }

