  public static void checkXMas()
  {
    DateTime now = DateTime.Now;
    int day = now.Day;
    int month = now.Month;
    Main.xMas = day >= 15 && month == 12;
    if (Main.forceXMasForToday)
      Main.xMas = true;
    if (!Main.forceXMasForever)
      return;
    Main.xMas = true;
  }

  public static bool isHalloweenDateNow()
  {
    DateTime now = DateTime.Now;
    int day = now.Day;
    int month = now.Month;
    if (day >= 10 && month == 10)
      return true;
    return day <= 1 && month == 11;
  }

  public static void checkHalloween()
  {
    Main.halloween = false;
    if (Main.isHalloweenDateNow())
      Main.halloween = true;
    if (Main.forceHalloweenForToday)
      Main.halloween = true;
    if (!Main.forceHalloweenForever)
      return;
    Main.halloween = true;
  }

  public void updateCloudLayer()
  {
    switch (Main.netMode)
