          return;
        break;
      case 1:
        return;
    }
    int num1 = 86400;
    int minValue = num1 / 24;
    float num2 = Math.Max(1f, (float) (1.0 + 4.0 * (double) Main.cloudAlpha));
    if ((double) Main.cloudBGActive > 0.0)
    {
