        Main.player[player].statMana = Main.player[player].statManaMax2;
        Main.player[player].breath = Main.player[player].breathMax;
      }
    }
    ++Main._gameUpdateCount;
    NPC.RevengeManager.Update();
    if (Main.netMode != 1)
    {
      try
