      --NPC.offSetDelayTime;
    if (Main.remixWorld && NPC.empressRageMode && !NPC.AnyNPCs(636))
      NPC.empressRageMode = false;
    if (Main.netMode != 1 && Main.afterPartyOfDoom && !BirthdayParty.PartyIsUp)
    {
      for (int number = 0; number < Main.maxNPCs; ++number)
