      }
    }
    LockOnHelper.SetUP();
    Main.CurrentFrameFlags.HadAnActiveInteractableProjectile = false;
    this.PreUpdateAllProjectiles();
    for (int i = 0; i < 1000; ++i)
    {
      Main.ProjectileUpdateLoopIndex = i;
      if (Main.ignoreErrors)
