  private static void MouseText_DrawItemTooltip_AddShopLines(
    Item hoverItem,
    ref int numLines,
    string[] lineText,
    Microsoft.Xna.Framework.Color[] lineColors)
  {
    if (Main.npcShop <= 0 || hoverItem.value < 0 || hoverItem.type >= 71 && hoverItem.type <= 74)
      return;
    long calcForSelling;
    long calcForBuying;
    Main.LocalPlayer.GetItemExpectedPrice(hoverItem, out calcForSelling, out calcForBuying);
    long num1 = hoverItem.isAShopItem || hoverItem.buyOnce ? calcForBuying : calcForSelling;
    if (hoverItem.shopSpecialCurrency != -1)
    {
      long price = num1 * (long) ItemSlot.EstimateDisplayStack(hoverItem);
      CustomCurrencyManager.GetPriceText(hoverItem.shopSpecialCurrency, lineText, ref numLines, price);
      lineColors[numLines - 1] = new Microsoft.Xna.Framework.Color((int) byte.MaxValue, (int) byte.MaxValue, (int) byte.MaxValue);
    }
    else if (num1 > 0L)
    {
      string str = "";
      long num2 = 0;
      long num3 = 0;
      long num4 = 0;
      long num5 = 0;
      long num6 = num1 * (long) ItemSlot.EstimateDisplayStack(hoverItem);
      if (!hoverItem.buy)
      {
        long num7 = num1 / 5L;
        if (num7 < 1L)
          num7 = 1L;
        long num8 = num7;
        num6 = num7 * (long) hoverItem.stack;
        int amount = Main.shopSellbackHelper.GetAmount(hoverItem);
        if (amount > 0)
          num6 += (-num8 + calcForBuying) * (long) Math.Min(amount, hoverItem.stack);
      }
      if (num6 < 1L)
        num6 = 1L;
      if (num6 >= 1000000L)
      {
        num2 = num6 / 1000000L;
        num6 -= num2 * 1000000L;
      }
      if (num6 >= 10000L)
      {
        num3 = num6 / 10000L;
        num6 -= num3 * 10000L;
      }
      if (num6 >= 100L)
      {
        num4 = num6 / 100L;
        num6 -= num4 * 100L;
      }
      if (num6 >= 1L)
        num5 = num6;
      if (num2 > 0L)
        str = $"{str}{(object) num2} {Lang.inter[15].Value} ";
      if (num3 > 0L)
        str = $"{str}{(object) num3} {Lang.inter[16 /*0x10*/].Value} ";
      if (num4 > 0L)
        str = $"{str}{(object) num4} {Lang.inter[17].Value} ";
      if (num5 > 0L)
        str = $"{str}{(object) num5} {Lang.inter[18].Value} ";
      lineText[numLines] = hoverItem.buy ? $"{Lang.tip[50].Value} {str}" : $"{Lang.tip[49].Value} {str}";
      if (num2 > 0L)
        lineColors[numLines] = new Microsoft.Xna.Framework.Color(220, 220, 198);
      else if (num3 > 0L)
        lineColors[numLines] = new Microsoft.Xna.Framework.Color(224 /*0xE0*/, 201, 92);
      else if (num4 > 0L)
        lineColors[numLines] = new Microsoft.Xna.Framework.Color(181, 192 /*0xC0*/, 193);
      else if (num5 > 0L)
        lineColors[numLines] = new Microsoft.Xna.Framework.Color(246, 138, 96 /*0x60*/);
      ++numLines;
    }
    else
    {
      if (hoverItem.type == 3817)
        return;
      lineText[numLines] = Lang.tip[51].Value;
      lineColors[numLines] = new Microsoft.Xna.Framework.Color(120, 120, 120);
      ++numLines;
    }
  }

