        int num = 120;
        toolTipLine[numLines] = Language.GetTextValue("CommonItemTooltip.RestoresLifeRange", (object) healLife, (object) num);
      }
      else
        toolTipLine[numLines] = Language.GetTextValue("CommonItemTooltip.RestoresLife", (object) obj1.healLife);
      ++numLines;
