  public static Vector2 DrawWhip_SlimeWhip(Projectile proj, List<Vector2> controlPoints)
  {
    int verticalFrames = 5;
    Texture2D texture2D = TextureAssets.Projectile[proj.type].Value;
    Microsoft.Xna.Framework.Rectangle r = texture2D.Frame(verticalFrames: verticalFrames);
    int height = r.Height;
    r.Height -= 2;
    Vector2 vector2 = r.Size() / 2f;
    Vector2 controlPoint1 = controlPoints[0];
    int num1 = 1;
    int num2 = (int) MathHelper.Max(1f, (float) (verticalFrames - 2));
    int num3 = controlPoints.Count - 1;
    for (int index = 0; index < num3; ++index)
    {
      bool flag = true;
      Vector2 origin = vector2;
      if (index == 0)
        r.Y = 0;
      else if (index == num3 - 1)
      {
        r.Y = height * (verticalFrames - 1);
      }
      else
      {
        float amount = (float) (((double) index - 1.0) / ((double) num3 - 2.0));
        int num4 = (int) Math.Round((double) MathHelper.Lerp((float) num1, (float) num2, amount));
        r.Y = height * num4;
        if (index % 3 != 0)
          flag = false;
      }
      Vector2 controlPoint2 = controlPoints[index];
      Vector2 v = controlPoints[index + 1] - controlPoint2;
      if (flag)
      {
        float rotation = v.ToRotation() - 1.57079637f;
        Microsoft.Xna.Framework.Color color = Lighting.GetColor(controlPoint2.ToTileCoordinates()) * 0.5f;
        Main.spriteBatch.Draw(texture2D, controlPoint1 - Main.screenPosition, new Microsoft.Xna.Framework.Rectangle?(r), color, rotation, origin, 1f, SpriteEffects.None, 0.0f);
      }
      controlPoint1 += v;
    }
    return controlPoint1;
  }

