  private static int TryPetting(Projectile proj, int itemIcon)
  {
    if (Main.gamePaused || Main.gameMenu)
      return 0;
    Player localPlayer = Main.LocalPlayer;
    Vector2 center = localPlayer.Center;
    if (!localPlayer.IsProjectileInteractableAndInInteractionRange(proj, ref center))
      return 0;
    Vector2 v = Main.ReverseGravitySupport(Main.MouseScreen) + Main.screenPosition;
    Microsoft.Xna.Framework.Rectangle hitbox = proj.Hitbox;
    if (proj.type == 1094)
      hitbox.Inflate(6, 6);
    bool flag1 = hitbox.Contains(v.ToPoint());
    int num = (flag1 ? 1 : (Main.SmartInteractProj == proj.whoAmI ? 1 : 0)) & (!localPlayer.lastMouseInterface ? 1 : 0);
    bool flag2 = !Main.SmartCursorIsUsed && !PlayerInput.UsingGamepad;
    if (num == 0)
      return !flag2 ? 1 : 0;
    Main.HasInteractableObjectThatIsNotATile = true;
    if (flag1)
    {
      localPlayer.noThrow = 4;
      localPlayer.cursorItemIconEnabled = true;
      localPlayer.cursorItemIconID = itemIcon;
    }
    if (PlayerInput.UsingGamepad)
      localPlayer.GamepadEnableGrappleCooldown();
