      if (rain.active)
      {
        rectangle.X = (int) rain.type * 4;
        Microsoft.Xna.Framework.Color color = Lighting.GetColor((int) ((double) rain.position.X + 4.0) >> 4, (int) ((double) rain.position.Y + 4.0) >> 4) * 0.85f;
