  public static void DrawNPCChatBottomRightItem(Vector2 bottomRight)
  {
    if (Main.npcChatCornerItem > 0)
    {
      bottomRight -= Vector2.One * 8f;
      Item I = new Item();
      I.SetDefaults(Main.npcChatCornerItem);
      float scale = 1f;
      Texture2D itemTexture;
      Microsoft.Xna.Framework.Rectangle itemFrame;
      Main.GetItemDrawFrame(I.type, out itemTexture, out itemFrame);
      if (itemFrame.Width > 32 /*0x20*/ || itemFrame.Height > 32 /*0x20*/)
        scale = itemFrame.Width <= itemFrame.Height ? 32f / (float) itemFrame.Height : 32f / (float) itemFrame.Width;
      Main.spriteBatch.Draw(itemTexture, bottomRight, new Microsoft.Xna.Framework.Rectangle?(itemFrame), I.GetAlpha(Microsoft.Xna.Framework.Color.White), 0.0f, itemFrame.Size(), scale, SpriteEffects.None, 0.0f);
      if (I.color != new Microsoft.Xna.Framework.Color())
        Main.spriteBatch.Draw(itemTexture, bottomRight, new Microsoft.Xna.Framework.Rectangle?(itemFrame), I.GetColor(I.color), 0.0f, itemFrame.Size(), scale, SpriteEffects.None, 0.0f);
      if (!new Microsoft.Xna.Framework.Rectangle((int) bottomRight.X - (int) ((double) itemFrame.Width * (double) scale), (int) bottomRight.Y - (int) ((double) itemFrame.Height * (double) scale), (int) ((double) itemFrame.Width * (double) scale), (int) ((double) itemFrame.Height * (double) scale)).Contains(new Microsoft.Xna.Framework.Point(Main.mouseX, Main.mouseY)))
        return;
      Main.cursorOverride = 2;
      if (Main.mouseLeftRelease && Main.mouseLeft)
      {
        if (!Main.drawingPlayerChat)
          Main.OpenPlayerChat();
        if (ChatManager.AddChatText(FontAssets.MouseText.Value, ItemTagHandler.GenerateTag(I), Vector2.One))
          SoundEngine.PlaySound(12);
      }
      Main.instance.MouseText(I.Name, -11);
    }
    else
    {
      if (Main.npcChatCornerItem != -1)
        return;
      bottomRight -= Vector2.One * 12f;
      Texture2D texture2D = TextureAssets.EquipPage[5].Value;
      float scale = 1f;
      Microsoft.Xna.Framework.Rectangle r = texture2D.Frame();
      if (r.Width > 32 /*0x20*/ || r.Height > 32 /*0x20*/)
        scale = r.Width <= r.Height ? 32f / (float) r.Height : 32f / (float) r.Width;
      Microsoft.Xna.Framework.Color white = Microsoft.Xna.Framework.Color.White;
      if (new Microsoft.Xna.Framework.Rectangle((int) bottomRight.X - (int) ((double) r.Width * (double) scale), (int) bottomRight.Y - (int) ((double) r.Height * (double) scale), (int) ((double) r.Width * (double) scale), (int) ((double) r.Height * (double) scale)).Contains(new Microsoft.Xna.Framework.Point(Main.mouseX, Main.mouseY)))
      {
        Main.spriteBatch.Draw(TextureAssets.EquipPage[7].Value, bottomRight, new Microsoft.Xna.Framework.Rectangle?(), Main.OurFavoriteColor, 0.0f, r.Size() + new Vector2(2f), scale, SpriteEffects.None, 0.0f);
        if (Main.mouseLeftRelease && Main.mouseLeft)
        {
          Main.CloseNPCChatOrSign(true);
          Player.OpenInventory();
          Main.EquipPageSelected = 1;
        }
      }
      Main.spriteBatch.Draw(texture2D, bottomRight, new Microsoft.Xna.Framework.Rectangle?(r), Microsoft.Xna.Framework.Color.White, 0.0f, r.Size(), scale, SpriteEffects.None, 0.0f);
    }
  }

