    float num6 = (float) Main.mouseTextColor / (float) byte.MaxValue;
    if (num1 > 0)
      chatColor = new Microsoft.Xna.Framework.Color((int) (byte) (220.0 * (double) num6), (int) (byte) (220.0 * (double) num6), (int) (byte) (198.0 * (double) num6), (int) Main.mouseTextColor);
    else if (num2 > 0)
      chatColor = new Microsoft.Xna.Framework.Color((int) (byte) (224.0 * (double) num6), (int) (byte) (201.0 * (double) num6), (int) (byte) (92.0 * (double) num6), (int) Main.mouseTextColor);
