      double num6 = Utils.Clamp<double>((double) num2, 0.0, max);
      Vector2 center = vector2_1 + new Vector2(0.0f, (float) y);
      num4 = (float) (Math.Sin(6.2831854820251465 * (num6 / max)) * 6.2831854820251465 * 0.0044999998062849045);
      vector2_1 = vector2_1.RotatedBy((double) num4, center);
    }
    if (num5 != 0)
    {
      double max = 80.0;
      float num7 = 0.25f;
      float num8 = (float) Utils.EaseOutBounce(Utils.Clamp<double>((double) num2, 0.0, max) / max);
      vector2_1 += new Vector2(0.0f, (float) ((double) -y * (double) num7 * (1.0 - (double) num8)));
    }
    if (flag)
    {
      double max = 120.0;
      int num9 = 30;
      double offsetX;
      double scaleX;
      Utils.GetPortraitMovement(Utils.Clamp<double>((double) num2, 0.0, max) / max, out offsetX, out scaleX);
      scale.X = (float) scaleX;
      vector2_1.X += (float) num9 * (float) offsetX;
      if ((double) scale.X < 0.0)
      {
        scale.X *= -1f;
        effects ^= SpriteEffects.FlipHorizontally;
