  private static void ReforgeItemInReforgeSlot()
  {
    Main.reforgeItem.ResetPrefix();
    bool rolledPrefixIsTopTier;
    Main.reforgeItem.Prefix(-2, out rolledPrefixIsTopTier);
    PopupText.NewText(rolledPrefixIsTopTier ? PopupTextContext.ItemReforge_Best : PopupTextContext.ItemReforge, Main.reforgeItem, Main.LocalPlayer.Center, Main.reforgeItem.stack, true);
    if (rolledPrefixIsTopTier)
    {
      SoundEngine.PlaySound(SoundID.BestReforge);
      Main.reforgeCooldown = 60;
      ParticleOrchestrator.RequestParticleSpawn(true, ParticleOrchestraType.RainbowRodHit, new ParticleOrchestraSettings()
      {
        PositionInWorld = Main.LocalPlayer.MountedCenter + new Vector2(0.0f, -16f * Main.LocalPlayer.gravDir),
        MovementVector = new Vector2(48f, 0.0f) + Main.rand.NextVector2Circular(16f, 16f)
      }, new int?(Main.myPlayer));
      ParticleOrchestrator.RequestParticleSpawn(true, ParticleOrchestraType.RainbowRodHit, new ParticleOrchestraSettings()
      {
        PositionInWorld = Main.LocalPlayer.MountedCenter + new Vector2(0.0f, -16f * Main.LocalPlayer.gravDir),
        MovementVector = new Vector2(0.0f, 16f) + Main.rand.NextVector2Circular(5f, 5f)
      }, new int?(Main.myPlayer));
      for (int index = 0; index < 3; ++index)
        ParticleOrchestrator.RequestParticleSpawn(true, ParticleOrchestraType.BestReforge, new ParticleOrchestraSettings()
        {
          PositionInWorld = Main.LocalPlayer.MountedCenter + Main.rand.NextVector2Circular(16f, 16f)
        }, new int?(Main.myPlayer));
    }
    else
      SoundEngine.PlaySound(SoundID.Item37);
  }

