    double num2 = 0.5;
    if (Main.masterMode)
      num2 = 1.0;
    else if (Main.expertMode)
      num2 = 0.75;
    int num3 = (int) Math.Ceiling((double) statDefense * num2);
    float difficulty = Main.Difficulty;
    if ((double) difficulty >= (double) GameDifficultyLevel.Expert)
    {
      frameX = 1;
      color1 = new Microsoft.Xna.Framework.Color((int) (byte) Main.DiscoR, (int) (byte) Main.DiscoG, (int) (byte) Main.DiscoB);
    }
