    {
      frameX = 2;
      float num4 = 6f;
      color1 = new Microsoft.Xna.Framework.Color((int) byte.MaxValue, (int) (byte) ((Math.Sin((double) Main.GlobalTimeWrappedHourly % (double) num4 / (double) num4 * 6.2831854820251465) * 0.5 + 0.5) * 120.0), 0);
    }
    if (frameX == 0 || statDefense == 0)
      color1 = Microsoft.Xna.Framework.Color.Transparent;
    Microsoft.Xna.Framework.Color color2 = color1 * Utils.Remap(MathHelper.Clamp((float) Math.Sin((double) Main.GlobalTimeWrappedHourly % (double) num1 / (double) num1 * 6.2831854820251465), 0.0f, 1f), 0.0f, 1f, 0.4f, 1f);
    Microsoft.Xna.Framework.Rectangle r = texture2D.Frame(3, 2, frameX);
    Microsoft.Xna.Framework.Rectangle rectangle = texture2D.Frame(3, 2, frameX, 1);
