    if (color2 != Microsoft.Xna.Framework.Color.Transparent)
      Main.spriteBatch.Draw(texture2D, vector2_1, new Microsoft.Xna.Framework.Rectangle?(rectangle), color2, 0.0f, origin, Main.inventoryScale, SpriteEffects.None, 0.0f);
