  public static string GetRecipeRequirementsText(Recipe recipe, bool explicitNone)
  {
    Main._requiredObjecsForCraftingText.Clear();
    if (recipe.requiredTile >= 0)
      Main._requiredObjecsForCraftingText.Add(Recipe.GetRequiredTileName(recipe.requiredTile));
    if (recipe.needWater)
      Main._requiredObjecsForCraftingText.Add(Lang.inter[53].Value);
    if (recipe.needHoney)
      Main._requiredObjecsForCraftingText.Add(Lang.inter[58].Value);
    if (recipe.needLava)
      Main._requiredObjecsForCraftingText.Add(Lang.inter[56].Value);
    if (recipe.needSnowBiome)
      Main._requiredObjecsForCraftingText.Add(Lang.inter[123].Value);
    if (recipe.needGraveyardBiome)
      Main._requiredObjecsForCraftingText.Add(Lang.inter[124].Value);
    if (recipe.needTorchGodsFavor)
      Main._requiredObjecsForCraftingText.Add(Lang.inter[125].Value);
    if (explicitNone && Main._requiredObjecsForCraftingText.Count == 0)
    {
      string str = Lang.inter[23].Value;
      Main._requiredObjecsForCraftingText.Add(str);
    }
    return $"{Lang.inter[22].Value} {string.Join(", ", (IEnumerable<string>) Main._requiredObjecsForCraftingText)}";
  }

