  public static void HoverOverCraftingItemButton(int recipeIndex)
  {
    Recipe recipe = Main.recipe[Main.availableRecipe[recipeIndex]];
    Main.player[Main.myPlayer].mouseInterface = true;
    bool flag1 = Main.mouseLeftRelease && Main.mouseLeft || Main.mouseRightRelease && Main.mouseRight;
    bool flag2 = Main.mouseLeft || Main.mouseRight;
    Main.craftingHide = true;
    Main.HoverItem = recipe.createItem.Clone();
    Main.HoverItem.tooltipSlot = 0;
    ItemSlot.MouseHover(22);
    if (ItemSlot.HoverOverrideClick(recipe.createItem, 22))
      Main._preventCraftingBecauseClickWasUsedToChangeFocusedRecipe = true;
    else if (Main.focusRecipe == recipeIndex && Main.guideItem.IsAir)
    {
      bool flag3 = !Main.LocalPlayer.UsingOrReusingItem && !Main.player[Main.myPlayer].IsLockedFromCrafting() && !Main._preventCraftingBecauseClickWasUsedToChangeFocusedRecipe;
      bool flag4 = ((Main._currentRecipeBeingCrafted == -1 ? 0 : (Main._currentRecipeBeingCrafted != Main.availableRecipe[recipeIndex] ? 1 : 0)) | (Main._currentRecipeBeingCrafted == -1 ? (false ? 1 : 0) : (Main.recipe[Main._currentRecipeBeingCrafted].createItem.maxStack == 1 ? 1 : 0))) != 0;
      int qty = Main.superFastStack + 1;
      if (ItemSlot.ShiftInUse)
        qty *= 10;
      if (((!flag2 ? 0 : (!flag4 ? 1 : 0)) & (flag3 ? 1 : 0)) != 0 && Main.stackSplit <= 1)
      {
        bool usingGamepad = PlayerInput.UsingGamepad;
        bool movedAnItemToAllowCrafting;
        int num = Main.TryAllowingToCraftRecipe(recipe, usingGamepad, out movedAnItemToAllowCrafting) ? 1 : 0;
        if (movedAnItemToAllowCrafting)
          Main._preventCraftingBecauseClickWasUsedToChangeFocusedRecipe = true;
        if (num != 0 && !movedAnItemToAllowCrafting)
        {
          if (Main._currentRecipeBeingCrafted == -1)
            Main._currentRecipeBeingCrafted = Main.availableRecipe[recipeIndex];
          ItemSlot.RefreshStackSplitCooldown();
          CraftingRequests.CraftItem(recipe, qty);
        }
      }
    }
    else if (flag1)
    {
      Main.focusRecipe = recipeIndex;
      Main.stackSplit = 15;
      Main._preventCraftingBecauseClickWasUsedToChangeFocusedRecipe = true;
      SoundEngine.PlaySound(12);
    }
    if (flag2)
      return;
    Main._preventCraftingBecauseClickWasUsedToChangeFocusedRecipe = false;
    Main._currentRecipeBeingCrafted = -1;
  }

  public static bool CursorHasSpaceToCraftRecipe(Recipe currentRecipe)
  {
    return Main.TryAllowingToCraftRecipe(currentRecipe, false, out bool _);
  }

  public static bool TryAllowingToCraftRecipe(
    Recipe currentRecipe,
    bool tryFittingItemInInventoryToAllowCrafting,
    out bool movedAnItemToAllowCrafting)
  {
    movedAnItemToAllowCrafting = false;
    Item mouseItem = Main.mouseItem;
    bool flag = false;
    if (!FakeCursorItem.Item.IsAir)
    {
      mouseItem = FakeCursorItem.Item;
      flag = true;
    }
    if (mouseItem.IsAir || !mouseItem.CanHavePrefixes() && Item.CanStack(mouseItem, currentRecipe.createItem) && mouseItem.stack + currentRecipe.createItem.stack <= mouseItem.maxStack)
      return true;
    if (tryFittingItemInInventoryToAllowCrafting && !flag && Main.LocalPlayer.ItemSpace(Main.mouseItem).CanTakeItemToPersonalInventory)
    {
      Main.mouseItem = Main.LocalPlayer.GetItem(Main.mouseItem, GetItemSettings.ReturnItemShowAsNewNoCoinMerge);
      if (Main.mouseItem.IsAir)
      {
        movedAnItemToAllowCrafting = true;
        return true;
      }
      if (!Main.mouseItem.CanHavePrefixes() && Item.CanStack(Main.mouseItem, currentRecipe.createItem) && Main.mouseItem.stack + currentRecipe.createItem.stack <= Main.mouseItem.maxStack)
      {
        movedAnItemToAllowCrafting = true;
        return true;
      }
    }
    return false;
  }

