  public static void CraftItem_GrantItem(Recipe recipe, Item result, bool quickCraft)
  {
    result.stack += Main.mouseItem.stack;
    Main.mouseItem = result;
    if (quickCraft)
    {
      if (CraftingRequests.HasPendingRequests)
      {
        Main.LocalPlayer.GetOrDropItem(Main.mouseItem, GetItemSettings.ReturnItemShowAsNew);
        Main.mouseItem.TurnToAir();
      }
      else
        Main.mouseItem = Main.LocalPlayer.GetItem(Main.mouseItem, GetItemSettings.ReturnItemShowAsNew);
    }
    CraftingEffects.OnCraftItemGranted(recipe, result, quickCraft);
    AchievementsHelper.NotifyItemCraft(recipe);
    AchievementsHelper.NotifyItemPickup(Main.player[Main.myPlayer], recipe.createItem);
  }

  private static void DrawPVPIcons()
  {
