    int num5 = num2 - 10;
    if (!Main.ShouldTeamSelectDraw)
      return;
    Microsoft.Xna.Framework.Rectangle rectangle1 = TextureAssets.Pvp[1].Frame(6);
    Microsoft.Xna.Framework.Rectangle r1 = rectangle1;
    for (int index = 0; index < 6; ++index)
    {
      r1.Location = new Microsoft.Xna.Framework.Point(num5 + index % 2 * 20, num4 + index / 2 * 20);
