      bool flag = false;
      if (r1.Contains(Main.MouseScreen.ToPoint()) && !PlayerInput.IgnoreMouseInterface)
      {
        Main.player[Main.myPlayer].mouseInterface = true;
        if (Main.teamCooldown == 0)
          flag = true;
        if (flag)
        {
          string str = "None";
          switch (index)
          {
            case 1:
              str = "Red";
              break;
            case 2:
              str = "Green";
              break;
            case 3:
              str = "Blue";
              break;
            case 4:
              str = "Yellow";
              break;
            case 5:
              str = "Pink";
              break;
          }
          string textValue = Language.GetTextValue($"UI.TeamIcon{str}{(Main.player[Main.myPlayer].team == index ? "_Active" : "_Inactive")}");
          Main.instance.MouseTextHackZoom(textValue);
        }
        if (Main.mouseLeft && Main.mouseLeftRelease && Main.player[Main.myPlayer].team != index && Main.teamCooldown == 0)
        {
          if (!Main.player[Main.myPlayer].TeamChangeAllowed())
          {
            Main.NewText(Lang.misc[84].Value, G: (byte) 240 /*0xF0*/, B: (byte) 20);
          }
          else
          {
            Main.teamCooldown = Main.teamCooldownLen;
            SoundEngine.PlaySound(12);
            Main.player[Main.myPlayer].team = index;
            if (Main.netMode != 0)
              NetMessage.SendData(157, number: Main.myPlayer);
            else if (Main.teamBasedSpawnsSeed)
              Main.player[Main.myPlayer].Spawn(PlayerSpawnContext.TeamSwap);
          }
        }
      }
      r1.Width = rectangle1.Width - 2;
      if (flag)
        Main.spriteBatch.Draw(TextureAssets.Pvp[2].Value, r1.Location.ToVector2() + new Vector2(-2f), Microsoft.Xna.Framework.Color.White);
      Microsoft.Xna.Framework.Rectangle rectangle2 = rectangle1;
