      Main.spriteBatch.Draw(TextureAssets.Pvp[1].Value, r1.Location.ToVector2(), new Microsoft.Xna.Framework.Rectangle?(rectangle2), Microsoft.Xna.Framework.Color.White);
      UILinkPointNavigator.SetPosition(1550 + index + 1, r1.Location.ToVector2() + r1.Size() * 0.75f);
    }
  }

