  private bool TryGetAmmo(
    Item sourceItem,
    out Item ammoItem,
    out Microsoft.Xna.Framework.Color ammoColor,
    out float ammoScale,
    out Vector2 ammoOffset)
  {
    ammoItem = (Item) null;
    ammoColor = Microsoft.Xna.Framework.Color.White;
    ammoScale = 0.8f;
    ammoOffset = Vector2.Zero;
    int type = sourceItem.type;
    switch (type)
    {
      case 1071:
      case 1072:
      case 1543:
      case 1544:
        int x = 22;
        int y = 22;
        if (type == 1072 || type == 1544)
        {
          x = 28;
          y = 28;
        }
        ammoOffset = new Vector2((float) x, (float) y);
        ammoItem = Main.player[Main.myPlayer].FindPaintOrCoating();
        return ammoItem != null;
      default:
        FlexibleTileWand flexibleTileWand = sourceItem.GetFlexibleTileWand();
        if (flexibleTileWand == null || !flexibleTileWand.ShowsHoverAmmoIcon || !flexibleTileWand.TryGetPlacementOption(Main.LocalPlayer, Player.FlexibleWandRandomSeed, Player.FlexibleWandCycleOffset, out FlexibleTileWand.PlacementOption _, out ammoItem))
          return false;
        ammoOffset = new Vector2(28f, 28f);
        return true;
    }
  }

