  internal static void HostAndPlay()
  {
    string str1 = $"-autoshutdown -password \"{Main.ConvertToSafeArgument(Netplay.ServerPassword)}\" -lang {(object) Language.ActiveCulture.LegacyId}";
    if (Platform.IsLinux)
      str1 = IntPtr.Size != 8 ? str1 + " -x86" : str1 + " -x64";
    string str2 = $"{(!Main.ActiveWorldFileData.IsCloudSave ? (object) (str1 + Main.SanitizePathArgument("world", Main.worldPathName)) : (object) (str1 + Main.SanitizePathArgument("cloudworld", Main.worldPathName)))} -worldrollbackstokeep {(object) Main.WorldRollingBackupsCountToKeep}";
    Netplay.HostToken = Main.NewToken();
    string str3 = $"{str2} -hosttoken {Netplay.HostToken}";
    Main.tServer = new Process();
    Main.tServer.StartInfo.FileName = !Platform.IsLinux ? (!Platform.IsOSX ? "TerrariaServer.exe" : "../MacOS/TerrariaServer") : "TerrariaServer";
    Main.tServer.StartInfo.Arguments = str3;
    if (Main.libPath != "")
    {
      ProcessStartInfo startInfo = Main.tServer.StartInfo;
      startInfo.Arguments = $"{startInfo.Arguments} -loadlib {Main.libPath}";
