  private void DrawPaladinsShield()
  {
    Player localPlayer = Main.LocalPlayer;
    if (localPlayer.dead)
      return;
    if (localPlayer.hasPaladinShield)
    {
      for (int index = 0; index < (int) byte.MaxValue; ++index)
      {
        if (index != Main.myPlayer)
        {
          Player player = Main.player[index];
          if (player.active && !player.dead && localPlayer.CanDefendWithPaladinsShield(player.team))
            this.DrawPaladinsShieldBoundary(localPlayer.MountedCenter, player.MountedCenter);
        }
      }
    }
    if (!localPlayer.defendedByPaladin)
      return;
    for (int index = 0; index < (int) byte.MaxValue; ++index)
    {
      if (index != Main.myPlayer)
      {
        Player player = Main.player[index];
        if (player.CanDefendWithPaladinsShield(localPlayer.team))
          this.DrawPaladinsShieldBoundary(player.MountedCenter, localPlayer.MountedCenter);
      }
    }
  }

