  private void RenderToTargets()
  {
    if (!Main.render)
      return;
    if (Main.renderNow || Main.renderCount == 1)
      Main.waterTarget.UpdateContent(new Action(this.RenderWater));
    else if (Main.renderNow || Main.renderCount == 2)
    {
      Main.backWaterTarget.UpdateContent(new Action(this.RenderBackgroundWater));
      Main.backgroundTargetSwap.UpdateContent(new Action(this.RenderBackground));
      Main.backgroundTargetSwapPending = true;
    }
    else if (Main.renderNow || Main.renderCount == 3)
    {
      Main.wallTarget.UpdateContent(new Action(this.RenderWallsAndBlacks));
      Main.tileTarget.UpdateContent(new Action(this.RenderTiles));
      Main.tile2Target.UpdateContent(new Action(this.RenderTiles2));
    }
    if (Main.tileTarget.IsPartiallyOffscreen)
      Main.tileTarget.UpdateContent(new Action(this.RenderTiles));
    if (Main.tile2Target.IsPartiallyOffscreen)
      Main.tile2Target.UpdateContent(new Action(this.RenderTiles2));
    if (Main.backWaterTarget.IsPartiallyOffscreen)
      Main.backWaterTarget.UpdateContent(new Action(this.RenderBackgroundWater));
    if (Main.backgroundTarget.IsPartiallyOffscreen)
    {
      this.ApplyPendingBackgroundTargetSwap();
      if (Main.backgroundTarget.IsPartiallyOffscreen)
        Main.backgroundTarget.UpdateContent(new Action(this.RenderBackground));
    }
    if (Main.wallTarget.IsPartiallyOffscreen)
      Main.wallTarget.UpdateContent(new Action(this.RenderWallsAndBlacks));
    if (!Main.waterTarget.IsPartiallyOffscreen)
      return;
    Main.waterTarget.UpdateContent(new Action(this.RenderWater));
  }

  protected void RenderTiles()
  {
    TimeLogger.StartTimestamp fromTimestamp = TimeLogger.Start();
    try
    {
      if (!DebugOptions.hideTiles)
      {
        this.TilesRenderer.PreDrawTiles(true, true);
        this.DrawTiles(true, true);
      }
    }
    catch (Exception ex)
    {
      if (Main.ignoreErrors)
        TimeLogger.DrawException(ex);
      else
        throw;
    }
    TimeLogger.RenderSolidTiles.AddTime(fromTimestamp);
  }

  protected void RenderTiles2()
  {
    TimeLogger.StartTimestamp fromTimestamp = TimeLogger.Start();
    try
    {
      if (!DebugOptions.hideTiles2)
      {
        this.TilesRenderer.PreDrawTiles(false, true);
        this.DrawTiles(false, true);
      }
    }
    catch (Exception ex)
    {
      if (Main.ignoreErrors)
        TimeLogger.DrawException(ex);
      else
        throw;
    }
    TimeLogger.RenderNonSolidTiles.AddTime(fromTimestamp);
  }

  protected void RenderWater()
  {
    TimeLogger.StartTimestamp fromTimestamp = TimeLogger.Start();
    Main.spriteBatch.Begin();
    Main.tileBatch.Begin();
    try
    {
      this.DrawWaters();
    }
    catch
    {
    }
    Main.tileBatch.End();
    Main.spriteBatch.End();
    TimeLogger.RenderLiquid.AddTime(fromTimestamp);
  }

  public static int CalculateWaterStyle(bool ignoreFountains = false)
  {
    if (Main.SceneMetrics.ActiveFountainColor >= 0 && !ignoreFountains)
      return Main.SceneMetrics.ActiveFountainColor;
    if (Main.bloodMoon && !Main.dayTime)
      return 9;
    switch (Main.bgStyle)
    {
      case 1:
      case 5:
        return 2;
      case 2:
        return Main.remixWorld || !Main.SceneMetrics.BelowSurface ? 6 : 12;
      case 3:
        return 3;
      case 4:
        return 13;
      case 6:
      case 13:
        return 4;
      case 7:
        return 5;
      case 8:
      case 14:
        return 10;
      default:
        if (Main.remixWorld)
        {
          if ((double) Main.SceneMetrics.TileCenter.Y > Main.rockLayer)
            return 7;
          if (Main.SceneMetrics.BelowSurface)
            return 8;
        }
        else
        {
          if ((double) Main.SceneMetrics.TileCenter.Y > Main.rockLayer + 40.0)
            return Main.SceneMetrics.ZoneGlowshroom ? 7 : 8;
          if (Main.SceneMetrics.BelowSurface)
            return 7;
        }
        return 0;
    }
  }

  public static bool IsLiquidStyleWater(int liquidStyle)
  {
    return liquidStyle != 1 && liquidStyle != 11 && liquidStyle != 14;
  }

  private void DrawWaters(bool isBackground = false)
  {
    if (DebugOptions.hideWater)
      return;
    TimeLogger.StartTimestamp fromTimestamp = TimeLogger.Start();
    Main.drewLava = false;
    if (!isBackground)
    {
      Main.waterStyle = Main.CalculateWaterStyle();
      for (int index = 0; index < 15; ++index)
      {
        if (Main.IsLiquidStyleWater(Main.waterStyle))
          Main.liquidAlpha[index] = Main.waterStyle == index ? Math.Min(Main.liquidAlpha[index] + 0.2f, 1f) : Math.Max(Main.liquidAlpha[index] - 0.2f, 0.0f);
      }
    }
    if (!Main.drawToScreen && !isBackground)
    {
      int firstTileX;
      int lastTileX;
      int firstTileY;
      int lastTileY;
      TileDrawing.GetScreenDrawArea(!Main.drawToScreen, out Vector2 _, out firstTileX, out lastTileX, out firstTileY, out lastTileY);
      Microsoft.Xna.Framework.Rectangle drawArea = new Microsoft.Xna.Framework.Rectangle(firstTileX, firstTileY, lastTileX - firstTileX, lastTileY - firstTileY);
      LiquidRenderer.Instance.PrepareDraw(drawArea);
    }
    bool flag = false;
    for (int index = 0; index < 15; ++index)
    {
      if (Main.IsLiquidStyleWater(index) && (double) Main.liquidAlpha[index] > 0.0 && index != Main.waterStyle)
      {
        this.DrawLiquid(isBackground, index, isBackground ? 1f : Main.liquidAlpha[index], true);
        flag = true;
      }
    }
    this.DrawLiquid(isBackground, Main.waterStyle, flag ? Main.liquidAlpha[Main.waterStyle] : 1f);
    if (isBackground)
      TimeLogger.DrawBackgroundWaterTiles.AddTime(fromTimestamp);
    else
      TimeLogger.DrawWaterTiles.AddTime(fromTimestamp);
  }

  protected void DrawLiquid(bool bg, int waterStyle, float Alpha = 1f, bool waterOnly = false)
