  private void ApplyPendingBackgroundTargetSwap()
  {
    if (!Main.backgroundTargetSwapPending)
      return;
    Utils.Swap<WorldSceneLayerTarget>(ref Main.backgroundTarget, ref Main.backgroundTargetSwap);
    Main.backgroundTargetSwapPending = false;
  }

  protected void RenderWallsAndBlacks()
  {
    this.ApplyPendingBackgroundTargetSwap();
    TimeLogger.StartTimestamp fromTimestamp = TimeLogger.Start();
    this.GraphicsDevice.DepthStencilState = new DepthStencilState()
    {
      DepthBufferEnable = true
    };
    this.RenderBlacks();
    this.RenderWalls();
    TimeLogger.RenderBlacksAndWalls.AddTime(fromTimestamp);
  }

  private void RenderBlacks()
  {
    if (DebugOptions.hideTiles)
      return;
    this.DrawBlack(true);
  }

  private void RenderWalls()
  {
    try
    {
      this.DrawWalls(true);
    }
    catch (Exception ex)
    {
      if (!Main.ignoreErrors)
        throw;
      TimeLogger.DrawException(ex);
    }
  }

