  private void DrawClouds_Distant(
    bool drawBackground,
    float backgroundTopMagicNumber,
    int pushBGTopHack,
    float globalCloudAlpha)
  {
    if (!drawBackground)
      return;
    float num = (float) ((double) backgroundTopMagicNumber * 750.0 + 830.0) + this.scAdj + (float) pushBGTopHack;
    if ((double) Main.screenPosition.Y >= Main.worldSurface * 16.0 + 16.0)
      return;
    this.StartDrawingClouds();
    for (int index = 0; index < 200; ++index)
    {
      Cloud theCloud = Main.cloud[index];
      if (theCloud.active && (double) theCloud.scale < 1.0)
      {
        float y = theCloud.position.Y;
        this.DrawCloud(globalCloudAlpha, theCloud, 1, y + num);
      }
    }
    this.EndDrawingClouds();
  }

  private void StartDrawingClouds() => this.HorizonRenderer.CloudsStart();

  private void EndDrawingClouds() => this.HorizonRenderer.CloudsEnd();

