  private void DrawSurfaceBG_DrawBackMountainsLayer(int bgTextureIndex)
  {
    if (bgTextureIndex < 0)
      return;
    this.LoadBackground(bgTextureIndex);
    int layerYoffset = this.DrawSurfaceBG_GetLayerYOffset(bgTextureIndex);
    this.bgTopY += (float) layerYoffset;
    for (int index = 0; index < this.bgLoops; ++index)
      Main.spriteBatch.Draw(TextureAssets.Background[bgTextureIndex].Value, new Vector2((float) (this.bgStartX + Main.bgWidthScaled * index), this.bgTopY), this.GetBackgroundRect(bgTextureIndex), Main.ColorOfSurfaceBackgroundsModified, 0.0f, new Vector2(), Main.bgScale, SpriteEffects.None, 0.0f);
    this.bgTopY -= (float) layerYoffset;
  }

