        this.bgTopY -= 50f;
      if (bgTexIndexes[0] == 53)
        this.bgTopY -= 100f;
      if (bgTexIndexes[0] == 91)
        this.bgTopY += 200f;
      if (bgTexIndexes[0] == 173)
        this.bgTopY += 200f;
