  protected override void Draw(GameTime gameTime)
  {
    if (this._isDrawingOrUpdating || !Main.IsGraphicsDeviceAvailable)
      return;
    this._isDrawingOrUpdating = true;
    DetailedFPS.Begin(DetailedFPS.OperationCategory.Draw);
    this.EnsureRenderTargetContent();
    this.DoDraw(gameTime);
    if (Main.OnPostDraw != null)
      Main.OnPostDraw(gameTime);
    Main.Assets.TransferCompletedAssets();
    DetailedFPS.End();
    this._isDrawingOrUpdating = false;
  }

  protected override void EndDraw()
  {
    if (this._isDrawingOrUpdating)
      return;
    if (Main.CollectGen0EveryFrame)
      NewRuntimeMethods.GC_Collect(0, GCCollectionMode.Forced, false);
    bool flag = false;
    if (Program.IsMono)
      flag = true;
    TimeSpan timeSpan;
    if (Main.FrameSkipMode == FrameSkipMode.Subtle && Main.improvedSubtleFrameSkip)
    {
      while (true)
      {
        do
        {
          long presentTimestamp = this.presentTimestamp;
          this.presentTimestamp = Stopwatch.GetTimestamp();
          double updateTimeAccumulator = Main.UpdateTimeAccumulator;
          timeSpan = Utils.SWTicksToTimeSpan(this.presentTimestamp - presentTimestamp);
          double totalSeconds = timeSpan.TotalSeconds;
          Main.UpdateTimeAccumulator = updateTimeAccumulator + totalSeconds;
          if (Main.UpdateTimeAccumulator < Main.TARGET_FRAME_TIME * 599.0 / 600.0)
            DetailedFPS.Begin(DetailedFPS.OperationCategory.Idle);
          else
            goto label_9;
        }
        while (flag || Main.UpdateTimeAccumulator >= Main.TARGET_FRAME_TIME * 0.9);
        flag = true;
        NewRuntimeMethods.GC_Collect(2, GCCollectionMode.Optimized, false);
      }
    }
label_9:
    DetailedFPS.Begin(DetailedFPS.OperationCategory.Present);
    if (Main.FrameSkipMode == FrameSkipMode.Subtle && Main.improvedSubtleFrameSkip && !flag)
    {
      timeSpan = DetailedFPS.CurrentFrameTime;
      if (timeSpan.TotalSeconds < Main.TARGET_FRAME_TIME * 0.9 && DetailedFPS.VsyncAppearsActive())
        NewRuntimeMethods.GC_Collect(2, GCCollectionMode.Optimized, false);
    }
    base.EndDraw();
    DetailedFPS.End();
    DetailedFPS.StartNextFrame();
  }

