  public static void UpdateSceneMetrics()
  {
    if (CaptureManager.Instance.IsCapturing)
      return;
    Player localPlayer = Main.LocalPlayer;
    Vector2 trackedPosition;
    Main._usingSeparateCameraSceneMetrics = Main.GetObjectTrackingCameraPan(out trackedPosition, out float _, out float _);
    if (Main._usingSeparateCameraSceneMetrics)
    {
      Main.LocalPlayer.UpdateSceneMetrics();
      if (Main.LocalPlayer.spectating >= 0)
        localPlayer = Main.player[Main.LocalPlayer.spectating];
    }
    else
      trackedPosition = Main.LocalPlayer.Center;
    Microsoft.Xna.Framework.Rectangle areaToLight = Main.GetAreaToLight();
    areaToLight.Inflate(28, 28);
    Main.SceneMetrics.Scan(new SceneMetricsScanSettings()
    {
      VisualScanArea = new Microsoft.Xna.Framework.Rectangle?(areaToLight),
      BiomeScanCenterPositionInWorld = trackedPosition,
      ScanNPCPositions = true,
      PerspectivePlayer = localPlayer
    });
  }

  public static void BlackFadeCameraTeleport()
  {
    Main.renderNow = true;
    NPC.ResetNetOffsets();
    Player.ResetNetOffsets();
    Main.BlackFadeIn = (int) byte.MaxValue;
    if (Main.mapTime < 5)
      Main.mapTime = 5;
    Main.maxQ = true;
    Lighting.Clear();
    Main.instantBGTransitionCounter = 10;
    Main.UpdateSceneMetrics();
    Main.SceneState.skipTransitions = true;
    Main.bgDelay = 0;
    Main.bgStyle = Main.GetPreferredBGStyleForPlayer();
    Cloud.lastCameraCenter = new Vector2?();
  }

  public static float BlackFadeDist
  {
    get => (float) ((double) Main.Camera.UnscaledSize.Length() / 2.0 + 100.0);
  }

  public static Vector2 PlayerFocusedScreenPosition()
  {
    return Main.LocalPlayer.Bottom + new Vector2(0.0f, Main.LocalPlayer.gfxOffY - 21f) + new Vector2(Main.cameraX, Main.cameraY) + Main.CurrentPan - Main.Camera.UnscaledSize * 0.5f;
  }

  public static void StartCameraTransitionForPlayerTeleport(
    Vector2 oldPosition,
    float lerp,
    int lerpSpeedupDelay)
  {
    if (Main.IsCameraTrackingObject)
    {
      Main.CurrentPan += oldPosition - Main.LocalPlayer.position;
    }
    else
    {
      oldPosition += Main.CurrentPan;
      Main.CurrentPan = Vector2.Zero;
      if ((double) Vector2.Distance(oldPosition, Main.LocalPlayer.position) < (double) Main.BlackFadeDist)
      {
        Main.SetCameraLerp(lerp, lerpSpeedupDelay);
      }
      else
      {
        Main.BlackFadeCameraTeleport();
        Main.screenPosition = Main.PlayerFocusedScreenPosition();
      }
    }
  }

  private static void DoDraw_UpdateCameraPosition()
  {
    if ((Main.gameMenu ? 0 : (Main.netMode != 2 ? 1 : 0)) == 0)
      return;
    if ((double) Main.cameraX != 0.0 && !Main.LocalPlayer.pulley)
      Main.cameraX = 0.0f;
    if ((double) Main.cameraX > 0.0)
    {
      --Main.cameraX;
      if ((double) Main.cameraX < 0.0)
        Main.cameraX = 0.0f;
    }
    if ((double) Main.cameraX < 0.0)
    {
      ++Main.cameraX;
      if ((double) Main.cameraX > 0.0)
        Main.cameraX = 0.0f;
    }
    if ((double) Main.cameraY > 0.0)
    {
      Main.cameraY -= 2f;
      if ((double) Main.cameraY < 0.0)
        Main.cameraY = 0.0f;
    }
    if ((double) Main.cameraY < 0.0)
    {
      Main.cameraY += 2f;
      if ((double) Main.cameraY > 0.0)
        Main.cameraY = 0.0f;
    }
    Vector2 screenPosition = Main.screenPosition;
    Main.screenPosition = Main.PlayerFocusedScreenPosition();
    if ((double) Main.cameraLerp > 0.0)
    {
      if ((double) Vector2.Distance(screenPosition, Main.screenPosition) - (double) Main.LocalPlayer.velocity.Length() < 0.25)
        Main.cameraLerp = 0.0f;
      else
        Main.screenPosition = Vector2.Lerp(screenPosition, Main.screenPosition, Main.cameraLerp);
    }
    Main.instance.CameraModifiers.ApplyTo(ref Main.screenPosition);
    Main.screenPosition.X = (float) (int) Main.screenPosition.X;
    Main.screenPosition.Y = (float) (int) Main.screenPosition.Y;
    Main.ClampScreenPositionToWorld();
  }

  public static void DebugCameraPan(bool left, bool right, bool up, bool down)
  {
    int num = 32 /*0x20*/;
    if (Main.keyState.IsKeyDown(Microsoft.Xna.Framework.Input.Keys.LeftShift))
      num *= 2;
    if (Main.keyState.IsKeyDown(Microsoft.Xna.Framework.Input.Keys.LeftControl))
      num /= 6;
    if (left)
      Main.screenPosition.X -= (float) num;
    if (right)
      Main.screenPosition.X += (float) num;
    if (up)
      Main.screenPosition.Y -= (float) num;
    if (!down)
      return;
    Main.screenPosition.Y += (float) num;
  }

  private static void UpdateCameraPan()
  {
    Main.LocalPlayer.netCameraTarget = new Vector2?();
    Main.disableDontStarveDarknessDamage = false;
    if (float.IsNaN(Main.CurrentPan.X))
      Main.CurrentPan.X = 0.0f;
    if (float.IsNaN(Main.CurrentPan.Y))
      Main.CurrentPan.Y = 0.0f;
    Vector2 targetPan = Vector2.Zero;
    float maxPanSpeed = 36f;
    Vector2 trackedPosition;
    float panRate;
    float doubleRateDist;
    if (Main.GetObjectTrackingCameraPan(out trackedPosition, out panRate, out doubleRateDist))
    {
