  public static Microsoft.Xna.Framework.Rectangle GetAreaToLight()
  {
    Vector2 vector2_1 = Main.Camera.ScaledPosition;
    Vector2 vector2_2 = Main.Camera.ScaledSize;
    if (!Lighting.UsingNewLighting)
    {
      vector2_1 = Main.Camera.UnscaledPosition;
      vector2_2 = Main.Camera.UnscaledSize;
    }
    int x = (int) Math.Floor((double) vector2_1.X / 16.0) - 1;
    int num1 = (int) Math.Floor(((double) vector2_1.X + (double) vector2_2.X) / 16.0) + 2;
    int y = (int) Math.Floor((double) vector2_1.Y / 16.0) - 1;
    int num2 = (int) Math.Floor(((double) vector2_1.Y + (double) vector2_2.Y) / 16.0) + 2;
    return new Microsoft.Xna.Framework.Rectangle(x, y, num1 - x, num2 - y);
  }

