    Microsoft.Xna.Framework.Rectangle worldPlayArea = WorldUtils.GetWorldPlayArea();
    Vector2 input1 = worldPlayArea.TopLeft() - Main.GameViewMatrix.Translation;
    Vector2 input2 = worldPlayArea.BottomRight() - Main.Camera.ScaledSize - Main.GameViewMatrix.Translation;
    Vector2 min = Utils.Round(input1);
    Vector2 max = Utils.Round(input2);
    Main.screenPosition = Vector2.Clamp(Main.screenPosition, min, max);
  }

  private static float ComputeScAdj(float screenY, float screenHeight)
  {
    float num1 = (float) (Main.worldSurface * 16.0) / (screenY + screenHeight);
    float num2 = (float) ((double) Main.maxTilesY * 0.15000000596046448 * 16.0) - screenY;
    if ((double) num2 < 0.0)
      num2 = 0.0f;
    float num3 = num2 * 0.00025f;
    float num4 = num3 * num3;
    float num5 = num1 * (0.45f - num4);
    return Main.maxTilesY > 1200 ? (Main.maxTilesY > 1800 ? num5 * -150f : num5 * -300f) : num5 * -500f;
  }

  private void DrawBG(SpriteBatchBeginner parentSpriteBatchBeginner)
  {
    this.scAdj = Main.ComputeScAdj(Main.screenPosition.Y, (float) Main.screenHeight);
    if (Main.gameMenu)
      this.scAdj = 0.0f;
    if (Main.resetClouds)
    {
      Cloud.resetClouds();
      Main.resetClouds = false;
    }
    Main.bgScale = 1f;
    Main.bgWidthScaled = (int) ((double) Main.backgroundWidth[Main.treeMntBGSet1[0]] * (double) Main.bgScale);
    Main.ColorOfSurfaceBackgroundsModified = Main.ColorOfTheSkies;
    Main.ColorOfSurfaceBackgroundsBase = Main.ColorOfTheSkies;
    int newBackgroundStyle = Main.GetPreferredBGStyleForPlayer();
    Main.backgroundLayerTransitionSpeed = 0.05f;
    if (Main.bgDelay < 0)
      ++Main.bgDelay;
    else if (newBackgroundStyle != Main.bgStyle)
      this.DrawBG_HandleBackgroundTransition(newBackgroundStyle);
    else if (Main.bgDelay > 0)
      --Main.bgDelay;
    if (Main.gameMenu)
    {
      Main.backgroundLayerTransitionSpeed = 0.02f;
      Main.bgStyle = Main.dayTime ? (!Main.notTheBeesWorld || Main.remixWorld ? 0 : 3) : 1;
      newBackgroundStyle = Main.bgStyle;
      if (WorldGen.drunkWorldGen)
        Main.bgStyle = !Main.onlyShimmerOceanWorldsGeneration ? (!Main.vampireSeed ? (!WorldGen.notTheBees ? 9 : 3) : 8) : 6;
    }
    if (Main.instantBGTransitionCounter > 0)
    {
      --Main.instantBGTransitionCounter;
      Main.bgStyle = newBackgroundStyle;
      Main.backgroundLayerTransitionSpeed = 1f;
    }
    this.UpdateBGVisibility_BackLayer(new int?(), new float?());
    this.UpdateBGVisibility_FrontLayer(new int?(), new float?());
    try
    {
      this.DrawSurfaceBG(parentSpriteBatchBeginner);
      if (!Main.BackgroundEnabled)
        return;
      this.DrawUnderworldBackground(Main.GameZoomTarget);
    }
    catch (Exception ex)
    {
      if (!Main.ignoreErrors)
        throw ex;
      TimeLogger.DrawException(ex);
    }
  }

  private void DrawBG_HandleBackgroundTransition(int newBackgroundStyle)
  {
    bool flag1 = SurfaceBackgroundID.Sets.IsForest[Main.bgStyle];
    bool flag2 = SurfaceBackgroundID.Sets.IsForest[newBackgroundStyle];
    if (!Main.gameMenu & flag1 & flag2 && WorldGen.GetCurrentBackgroundOfStyle(Main.bgStyle) == WorldGen.GetCurrentBackgroundOfStyle(newBackgroundStyle))
    {
      Main.instantBGTransitionCounter = 1;
    }
    else
    {
      int num = flag2 ? 60 : 30;
      ++Main.bgDelay;
      if (Main.bgDelay <= num)
        return;
      Main.bgDelay = -60;
      Main.bgStyle = newBackgroundStyle;
      if (!flag2)
        return;
      Main.bgDelay = 0;
    }
  }

  private void UpdateBGVisibility_FrontLayer(
    int? targetBiomeOverride,
    float? transitionAmountOverride)
  {
    int bgStyle = Main.bgStyle;
    if (targetBiomeOverride.HasValue)
      bgStyle = targetBiomeOverride.Value;
    float layerTransitionSpeed = Main.backgroundLayerTransitionSpeed;
    if (transitionAmountOverride.HasValue)
      layerTransitionSpeed = transitionAmountOverride.Value;
    for (int originalBiome = 0; originalBiome < Main.bgAlphaFrontLayer.Length; ++originalBiome)
    {
      if (bgStyle == originalBiome)
      {
        Main.bgAlphaFrontLayer[originalBiome] += layerTransitionSpeed;
        if ((double) Main.bgAlphaFrontLayer[originalBiome] > 1.0)
          Main.bgAlphaFrontLayer[originalBiome] = 1f;
      }
      else if ((double) Main.bgAlphaFrontLayer[originalBiome] != 0.0 && (!this.UpdateBGVisibility_FrontLayer_IsDesertVariantSwap(bgStyle, originalBiome) || (double) Main.bgAlphaFrontLayer[bgStyle] >= 1.0))
      {
        Main.bgAlphaFrontLayer[originalBiome] -= layerTransitionSpeed;
        if ((double) Main.bgAlphaFrontLayer[originalBiome] < 0.0)
          Main.bgAlphaFrontLayer[originalBiome] = 0.0f;
      }
    }
  }

  private bool UpdateBGVisibility_FrontLayer_IsDesertVariantSwap(int targetBiome, int originalBiome)
  {
    if (targetBiome == originalBiome || !SurfaceBackgroundID.Sets.IsDesertVariant[targetBiome] || !SurfaceBackgroundID.Sets.IsDesertVariant[originalBiome])
      return false;
    Func<int, bool> func = (Func<int, bool>) (bg =>
    {
      switch (bg)
      {
        case 2:
          return Main.desertBackgroundSet.Pure.HasAny;
        case 5:
          return Main.desertBackgroundSet.Corrupt.HasAny;
        case 13:
          return Main.desertBackgroundSet.Hallow.HasAny;
        case 14:
          return Main.desertBackgroundSet.Crimson.HasAny;
        default:
          return false;
      }
    });
    return func(targetBiome) && func(originalBiome);
  }

  private void UpdateBGVisibility_BackLayer(
    int? targetBiomeOverride,
    float? transitionAmountOverride)
  {
    int bgStyle = Main.bgStyle;
    if (targetBiomeOverride.HasValue)
      bgStyle = targetBiomeOverride.Value;
    double layerTransitionSpeed = (double) Main.backgroundLayerTransitionSpeed;
    if (transitionAmountOverride.HasValue)
    {
      double num = (double) transitionAmountOverride.Value;
    }
    switch (bgStyle)
    {
      case 1:
      case 5:
      case 13:
      case 14:
        this.DrawBG_ModifyBGFarBackLayerAlpha(2, transitionAmountOverride: transitionAmountOverride);
        break;
      case 2:
        this.DrawBG_ModifyBGFarBackLayerAlpha(1, transitionAmountOverride: transitionAmountOverride);
        break;
      case 3:
        if (WorldGen.jungleBG == 5)
        {
          this.DrawBG_ModifyBGFarBackLayerAlpha(15, transitionAmountOverride: transitionAmountOverride);
          break;
        }
        this.DrawBG_ModifyBGFarBackLayerAlpha(0, transitionAmountOverride: transitionAmountOverride);
        break;
      case 4:
        this.DrawBG_ModifyBGFarBackLayerAlpha(3, transitionAmountOverride: transitionAmountOverride);
        break;
      case 6:
        if (WorldGen.hallowBG == 3)
        {
          this.DrawBG_ModifyBGFarBackLayerAlpha(6, transitionAmountOverride: transitionAmountOverride);
          break;
        }
        this.DrawBG_ModifyBGFarBackLayerAlpha(2, transitionAmountOverride: transitionAmountOverride);
        break;
      case 7:
        this.DrawBG_ModifyBGFarBackLayerAlpha(4, transitionAmountOverride: transitionAmountOverride);
        break;
      case 8:
        this.DrawBG_ModifyBGFarBackLayerAlpha(5, transitionAmountOverride: transitionAmountOverride);
        break;
      case 9:
        this.DrawBG_ModifyBGFarBackLayerAlpha(0, new int?(6), transitionAmountOverride);
        break;
      case 10:
      case 11:
      case 12:
        this.DrawBG_ModifyBGFarBackLayerAlpha(bgStyle, transitionAmountOverride: transitionAmountOverride);
        break;
      default:
        this.DrawBG_ModifyBGFarBackLayerAlpha(0, transitionAmountOverride: transitionAmountOverride);
        break;
    }
  }

  public static int GetPreferredBGStyleForPlayer()
  {
    int bgStyle = Main.bgStyle;
    int num = (int) (((double) Main.screenPosition.X + (double) (Main.screenWidth / 2)) / 16.0);
    int bgStyleForPlayer;
    if (Main.SceneMetrics.ZoneBeach)
      bgStyleForPlayer = !Main.SceneMetrics.ZoneHallow ? (!Main.SceneMetrics.ZoneCorrupt ? (!Main.SceneMetrics.ZoneCrimson ? (Main.SceneMetrics.HoneyBlockCount <= 400 ? 4 : 3) : 8) : (Main.SceneMetrics.BloodTileCount <= Main.SceneMetrics.EvilTileCount ? 1 : 8)) : 6;
    else if (Main.SceneMetrics.ZoneGlowshroom)
      bgStyleForPlayer = 9;
    else if (Main.SceneMetrics.ZoneDesert)
      bgStyleForPlayer = !Main.SceneMetrics.ZoneCorrupt || Main.SceneMetrics.EvilTileCount <= Main.SceneMetrics.BloodTileCount || Main.SceneMetrics.EvilTileCount <= Main.SceneMetrics.HolyTileCount ? (!Main.SceneMetrics.ZoneCrimson || Main.SceneMetrics.BloodTileCount <= Main.SceneMetrics.HolyTileCount ? (!Main.SceneMetrics.ZoneHallow ? 2 : 13) : 14) : 5;
    else if (Main.SceneMetrics.ZoneHallow)
      bgStyleForPlayer = 6;
    else if (Main.SceneMetrics.ZoneCorrupt)
      bgStyleForPlayer = Main.SceneMetrics.BloodTileCount <= Main.SceneMetrics.EvilTileCount ? 1 : 8;
    else if (Main.SceneMetrics.ZoneCrimson)
      bgStyleForPlayer = 8;
    else if (Main.SceneMetrics.ZoneJungle)
      bgStyleForPlayer = 3;
    else if (Main.SceneMetrics.ZoneSnow)
    {
      bgStyleForPlayer = 7;
    }
    else
    {
      bgStyleForPlayer = 0;
      if (num >= Main.treeX[0])
        bgStyleForPlayer = num >= Main.treeX[1] ? (num >= Main.treeX[2] ? 12 : 11) : 10;
    }
    return bgStyleForPlayer;
  }

  private void DrawBG_ModifyBGFarBackLayerAlpha(
    int desiredBG,
    int? desiredBG2 = null,
