    for (int originalBiome = 0; originalBiome < Main.bgAlphaFarBackLayer.Length; ++originalBiome)
    {
      int num1 = desiredBG == originalBiome ? 1 : 0;
      int num2;
      if (desiredBG2.HasValue)
      {
        int? nullable = desiredBG2;
        int num3 = originalBiome;
        num2 = nullable.GetValueOrDefault() == num3 & nullable.HasValue ? 1 : 0;
      }
      else
        num2 = 0;
      bool flag = (num1 | num2) != 0;
      if (flag || (double) Main.bgAlphaFarBackLayer[originalBiome] != 0.0 && (!this.UpdateBGVisibility_FrontLayer_IsDesertVariantSwap(desiredBG, originalBiome) || (double) Main.bgAlphaFarBackLayer[desiredBG] >= 1.0))
        Main.bgAlphaFarBackLayer[originalBiome] = MathHelper.Clamp(Main.bgAlphaFarBackLayer[originalBiome] + (flag ? layerTransitionSpeed : -layerTransitionSpeed), 0.0f, 1f);
