  public static bool IsRainingForever => Main.rainTime >= 5184000;

  public static void StopRain(bool instant = false)
  {
    if (Main.IsRainingForever)
      return;
    Main.rainTime = 0;
    Main.raining = false;
    Main.maxRaining = 0.0f;
    Main.coinRain = 0;
    if (!instant)
      return;
    Main.cloudAlpha = Main.maxRaining;
  }

  public static void StartRain(bool instant = false, float? strengthOverride = null, bool garenteeCoinRain = false)
  {
    if (!Main.remixWorld && Main.isThereAWorldSurface && !Main.raining)
    {
      int range = 25;
      if (Main.tenthAnniversaryWorld && !Main.getGoodWorld)
        range = 5;
      if (Player.GetPlayerWithHighestLuck().RollLuck(range) == 0 | garenteeCoinRain)
      {
        float num = (float) Main.maxTilesX / 4200f;
        switch (Main.netMode)
        {
          case 0:
            Main.NewText(Lang.gen[93].Value, G: (byte) 200, B: (byte) 150);
            break;
          case 2:
            ChatHelper.BroadcastChatMessage(NetworkText.FromKey(Lang.gen[93].Key), new Microsoft.Xna.Framework.Color((int) byte.MaxValue, 200, 150));
            break;
        }
        Main.coinRain = Main.rand.Next(75, 151) * 100 * 100;
        Main.coinRain = (int) ((double) Main.coinRain * (double) num);
      }
    }
    int maxValue1 = 86400;
    int maxValue2 = maxValue1 / 24;
