  public static void StartSlimeRain(bool announce = true)
  {
    if (Main.remixWorld || !Main.isThereAWorldSurface || Main.slimeRain)
      return;
    if (Main.netMode == 1)
    {
      if (announce)
      {
        NetMessage.SendData(61, number: Main.myPlayer, number2: -19f);
      }
      else
      {
        Main.slimeRainTime = 54000.0;
        Main.slimeRain = true;
        SkyManager.Instance.Activate("Slime");
      }
    }
    else
    {
      if (Main.raining)
        return;
      if (Main.slimeRainTime <= 0.0)
        Main.slimeRainTime = (double) Main.rand.Next(32400, 54000);
      Main.slimeRain = true;
      Main.slimeRainKillCount = 0;
      if (Main.netMode == 0)
      {
        SkyManager.Instance.Activate("Slime");
        if (!announce)
          return;
        Main.slimeWarningTime = Main.slimeWarningDelay;
      }
      else
      {
        if (!announce)
          return;
        Main.slimeWarningTime = Main.slimeWarningDelay;
        NetMessage.SendData(7);
      }
    }
  }

  public static void StopSlimeRain(bool announce = true)
