  public static bool IsFullScreenThatWouldBeStuckOnCrashMessage()
  {
    if (Main.dedServ)
      return false;
    return Main.graphics == null || Main.graphics.IsFullScreen;
  }

  public static void ClearPendingPlayerSelectCallbacks()
  {
    Main._pendingCharacterSelect = (Action) null;
  }

  public static void SelectPlayer(PlayerFileData data)
  {
    if (data.Player.loadStatus != StatusID.Ok)
      throw new Exception("Tried to select a player with loadStatus: " + (object) data.Player.loadStatus);
    Main.myPlayer = 0;
    Main.ServerSideCharacter = false;
    data.SetAsActive();
    if (Main._pendingCharacterSelect != null)
    {
      Main._pendingCharacterSelect();
      Main._pendingCharacterSelect = (Action) null;
    }
    else if (Main.menuMultiplayer)
    {
      SoundEngine.PlaySound(10);
      if (Main.autoJoin)
      {
        if (Netplay.SetRemoteIP(Main.getIP))
        {
          Main.menuMode = 10;
          Netplay.StartTcpClient();
        }
        Main.autoJoin = false;
      }
      else if (Main.menuServer)
      {
        Main.LoadWorlds();
        Main.menuMode = 6;
      }
      else
      {
        Main.menuMode = 13;
        Main.clrInput();
      }
    }
    else
    {
      Main.LocalPlayer.position = Vector2.Zero;
      Main.LoadWorlds();
      SoundEngine.PlaySound(10);
      Main.menuMode = 6;
    }
  }

